import "dotenv/config";
import { defineConfig, env } from "prisma/config";

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
    seed: "tsx prisma/seed.ts",
  },
  datasource: {
    url: env("DATABASE_URL"),
  },
});

generator client {
  provider = "prisma-client"
  output   = "../src/generated/prisma"
}

datasource db {
  provider = "postgresql"
}

enum OrderStatus {
  PENDING
  PAID
  SHIPPED
  CANCELLED
}

model Customer {
  id        Int      @id @default(autoincrement())
  email     String   @unique
  fullName  String
  createdAt DateTime @default(now())

  orders Order[]
}

model Order {
  id         Int         @id @default(autoincrement())
  reference  String      @unique
  status     OrderStatus @default(PENDING)
  totalCents Int
  placedAt   DateTime    @default(now())

  customer   Customer @relation(fields: [customerId], references: [id])
  customerId Int

  @@index([customerId, placedAt])
}

datasource db {
  provider = "postgresql"
  // The URL is not stored here in Prisma 7; it lives in prisma.config.ts
}

datasource db {
  provider     = "mysql"
  // Emulate foreign keys for databases such as PlanetScale that do not enforce them
  relationMode = "prisma"
}

model Author {
  id      Int      @id @default(autoincrement())
  email   String   @unique
  profile Profile?
  books   Book[]
}

model Profile {
  id       Int    @id @default(autoincrement())
  bio      String
  author   Author @relation(fields: [authorId], references: [id], onDelete: Cascade)
  // Unique turns the back-reference into a one-to-one relation
  authorId Int    @unique
}

model Book {
  id       Int    @id @default(autoincrement())
  title    String
  author   Author @relation(fields: [authorId], references: [id], onDelete: Restrict)
  authorId Int
  tags     Tag[]
}

model Tag {
  id    Int    @id @default(autoincrement())
  label String @unique
  books Book[]
}

model Student {
  id       Int          @id @default(autoincrement())
  name     String
  courses  Enrollment[]
}

model Course {
  id       Int          @id @default(autoincrement())
  code     String       @unique
  students Enrollment[]
}

model Enrollment {
  student   Student  @relation(fields: [studentId], references: [id], onDelete: Cascade)
  studentId Int
  course    Course   @relation(fields: [courseId], references: [id], onDelete: Cascade)
  courseId  Int
  grade     Int?
  signedAt  DateTime @default(now())

  @@id([studentId, courseId])
}

import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "../generated/prisma/client";

const globalForPrisma = globalThis as unknown as { prisma?: PrismaClient };

export const prisma =
  globalForPrisma.prisma ??
  new PrismaClient({
    adapter: new PrismaPg({ connectionString: process.env.DATABASE_URL! }),
    log: ["warn", "error"],
  });

// Reuse the instance across hot reloads instead of opening a pool per reload
if (process.env.NODE_ENV !== "production") {
  globalForPrisma.prisma = prisma;
}

import { prisma } from "./prisma";

async function main() {
  await prisma.$connect();

  const customers = await prisma.customer.count();
  console.log(`${customers} customers`);
}

// Close the adapter pool so the process can exit without hanging
process.once("SIGTERM", () => {
  void prisma.$disconnect();
});

main().catch(async (error) => {
  console.error(error);
  await prisma.$disconnect();
  process.exitCode = 1;
});

// Insert one row and get the generated id back
const customer = await prisma.customer.create({
  data: { email: "grace@example.com", fullName: "Grace Hopper" },
});

// Insert several rows in one round trip; duplicates are ignored
await prisma.product.createMany({
  data: [
    { sku: "KB-01", title: "Mechanical keyboard", price: "89.90", stock: 12 },
    { sku: "MS-02", title: "Wireless mouse", price: "39.90", stock: 30 },
  ],
  skipDuplicates: true,
});

// Insert or update in a single call, keyed by the unique email
await prisma.customer.upsert({
  where: { email: "ada@example.com" },
  update: { fullName: "Ada Lovelace" },
  create: { email: "ada@example.com", fullName: "Ada Lovelace" },
});

const byEmail = await prisma.customer.findUnique({
  where: { email: "grace@example.com" },
});

const paidCustomers = await prisma.customer.findMany({
  where: { orders: { some: { status: "PAID" } } },
  orderBy: { createdAt: "desc" },
  take: 20,
});

const oldestPending = await prisma.order.findFirst({
  where: { status: "PENDING" },
  orderBy: { placedAt: "asc" },
});

await prisma.order.update({
  where: { reference: "ORD-1001" },
  data: { status: "SHIPPED" },
});

const cancelled = await prisma.order.updateMany({
  where: { status: "PENDING", placedAt: { lt: new Date("2026-01-01") } },
  data: { status: "CANCELLED" },
});

await prisma.order.delete({ where: { reference: "ORD-0999" } });

const removed = await prisma.customer.deleteMany({
  where: { orders: { none: { status: "PAID" } } },
});

const customers = await prisma.customer.findMany({
  select: {
    email: true,
    fullName: true,
    _count: { select: { orders: true } },
    orders: {
      select: { reference: true, status: true },
      orderBy: { placedAt: "desc" },
      take: 3,
    },
  },
});

const order = await prisma.order.findUnique({
  where: { reference: "ORD-1001" },
  include: { customer: true },
});

const page = await prisma.product.findMany({
  orderBy: [{ title: "asc" }, { id: "asc" }],
  cursor: { id: 41 },
  skip: 1,
  take: 15,
});

// One row per distinct value of the selected column
const statuses = await prisma.order.findMany({
  distinct: ["status"],
  select: { status: true },
});

const totals = await prisma.order.aggregate({
  where: { status: "PAID" },
  _sum: { totalCents: true },
  _avg: { totalCents: true },
  _count: { _all: true },
});

const perCustomer = await prisma.order.groupBy({
  by: ["customerId"],
  where: { status: "PAID" },
  _sum: { totalCents: true },
  orderBy: { customerId: "asc" },
});

const products = await prisma.product.findMany({
  where: {
    title: { contains: "keyboard", mode: "insensitive" },
    price: { gte: "50.00", lt: "150.00" },
    sku: { in: ["KB-01", "KB-02", "KB-03"] },
    tags: { has: "wireless" },
  },
  orderBy: { price: "desc" },
});

const flagged = await prisma.customer.findMany({
  where: {
    OR: [
      { orders: { some: { status: "CANCELLED" } } },
      { orders: { none: { status: "PAID" } } },
    ],
    NOT: { email: { endsWith: "@internal.example" } },
  },
  select: { email: true },
});

const vip = await prisma.order.findMany({
  where: {
    AND: [
      { customer: { is: { email: { contains: "+vip" } } } },
      { totalCents: { gt: 10000 } },
    ],
  },
});

const placed = await prisma.order.findMany({
  where: {
    status: { not: "CANCELLED" },
    placedAt: { gte: new Date("2026-01-01"), lt: new Date("2026-07-01") },
  },
  orderBy: [{ status: "asc" }, { placedAt: "desc" }],
});

const [order, product] = await prisma.$transaction([
  prisma.order.create({
    data: { reference: "ORD-1042", totalCents: 4800, customerId: 7 },
  }),
  prisma.product.update({
    where: { sku: "KB-01" },
    data: { stock: { decrement: 1 } },
  }),
]);

const order = await prisma.$transaction(
  async (tx) => {
    const created = await tx.order.create({
      data: { reference: "ORD-1043", totalCents: 9900, customerId: 7 },
    });

    await tx.product.update({
      where: { sku: "KB-01" },
      data: { stock: { decrement: 2 } },
    });

    return created;
  },
  { isolationLevel: "Serializable", maxWait: 2000, timeout: 8000 },
);

import { Prisma } from "../generated/prisma/client";

const statuses = ["PAID", "SHIPPED"];
const direction = Prisma.raw("DESC");

const rows = await prisma.$queryRaw`
  SELECT "reference", "totalCents"
  FROM "Order"
  WHERE "status" IN (${Prisma.join(statuses)})
  ORDER BY "placedAt" ${direction}
  LIMIT 25
`;

import "dotenv/config";
import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "../src/generated/prisma/client";

const prisma = new PrismaClient({
  adapter: new PrismaPg({ connectionString: process.env.DATABASE_URL! }),
});

async function main() {
  const customer = await prisma.customer.upsert({
    where: { email: "ada@example.com" },
    update: { fullName: "Ada Lovelace" },
    create: { email: "ada@example.com", fullName: "Ada Lovelace" },
  });

  await prisma.order.upsert({
    where: { reference: "ORD-1001" },
    update: {},
    create: {
      reference: "ORD-1001",
      totalCents: 12900,
      status: "PAID",
      customerId: customer.id,
    },
  });
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());

import { Prisma } from "../generated/prisma/client";

export function explain(error: unknown): string {
  if (error instanceof Prisma.PrismaClientKnownRequestError) {
    switch (error.code) {
      case "P2002": // unique constraint failed
        return "A unique value is already in use.";
      case "P2003": // foreign key constraint failed
        return "A related row is missing or still referenced.";
      case "P2025": // record required by the operation was not found
        return "The record no longer exists.";
      default:
        return `Database error ${error.code}`;
    }
  }

  if (error instanceof Prisma.PrismaClientInitializationError) {
    return "Cannot reach the database; check DATABASE_URL and that Postgres is up.";
  }

  return "Unexpected database failure.";
}
